        b: Range<usize>,
        expected: [Range<usize>; N],
    ) {
        let mut res = range_difference(&a, &b);
        self::__spec_each_state(expected
            .into_iter(), &mut res, |__spec_callback_state: &mut _, val| match (&((*__spec_callback_state).next()), &(Some(val))) { (left_val, right_val) => { if !(*left_val == *right_val) { self::checked_eq_failure(&*left_val, &*right_val); } } });
        assert!(res.next().is_none());
    }
